<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientFrontChannelLogoutUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientFrontChannelLogoutUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withFrontChannelLogoutUri,
 * getFrontChannelLogoutUri/frontChannelLogoutUri accessors, and isFrontChannelLogoutUriChanged with/without original.
 */
class TrustedClientFrontChannelLogoutUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withFrontChannelLogoutUri creates a new instance with the FrontChannelLogoutUri set
     * from a string value, and getFrontChannelLogoutUri returns the primitive string.
     */
    public function testWithFrontChannelLogoutUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientFrontChannelLogoutUriAccessorUnitTest();

        // Act
        $result = $holder->withFrontChannelLogoutUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getFrontChannelLogoutUri());
    }
    /**
     * Asserts that withfrontChannelLogoutUri has access to the value object
     * from a string value, and getFrontChannelLogoutUri returns the primitive string.
     */
    public function testWithFrontChannelLogoutUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientFrontChannelLogoutUriAccessorUnitTest();

        // Act
        $result = $holder->withFrontChannelLogoutUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->frontChannelLogoutUri()->value());
    }
    public function testChangedFrontChannelLogoutUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientFrontChannelLogoutUriAccessorUnitTest();
        $original = $holder->withFrontChannelLogoutUri('one');
        $same = $holder->withFrontChannelLogoutUri('one');
        $modified = $holder->withFrontChannelLogoutUri('other');

        // Act
        $unchanged = $holder->isFrontChannelLogoutUriChanged();
        $withSame = $original->isFrontChannelLogoutUriChanged($same);
        $withDiferent = $original->isFrontChannelLogoutUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientFrontChannelLogoutUriAccessorUnitTest
{
    use TrustedClientFrontChannelLogoutUriAccessor;
}
